/**
 * Get the license types.
 *
 * @since x.x
 *
 * @param string $case Use 'lowercase' to return lowercase license types.
 * @return array
 */
public static function get_license_types( $case = 'titlecase' ) {
	$license_types = array( 'Basic', 'Plus', 'Business', 'Elite' );

	if ( 'lowercase' === $case ) {
		$license_types = array_map( 'strtolower', $license_types );
	}

	return $license_types;
}

